from pathlib import Path
import base64
Path('docs/HANDOFF_NEXT_CHAT.md').write_bytes(base64.b64decode(''))

p=Path('docs/ARCHITECTURE.md'); s=p.read_text()
old='The Wi-Fi Plug Detail keeps editable Device cards. A BLE-only Plug uses the same product taxonomy but currently exposes Device as a compact read-only summary: LED mode plus supported brightness/night-mode state, physical-button mode and Shelly Cloud enabled/connection state. That BLE surface must not grow mutation controls until a mutation-specific product and transport contract is explicitly approved.'
new='The Wi-Fi Plug Detail keeps editable Device cards. A BLE-origin Plug keeps LED/brightness/night-mode, physical-button mode and Shelly Cloud as a compact read-only summary. Capability-aware Wi-Fi provisioning and device-time synchronization are explicitly approved outside those read-only cards. Firmware maintenance is exposed after a verified Wi-Fi locator exists. Optional mutations are capability-checked and identity-verified before use.'
assert old in s
s=s.replace(old,new)
old='- mutating BLE RPC stays outside locator recovery and is never automatically replayed after an ambiguous failure;\n- no automatic BLE↔Wi-Fi fallback or transport merging is implemented yet.'
new='- mutating BLE RPC stays outside locator recovery and is never automatically replayed after an ambiguous failure;\n- capability discovery uses `Shelly.ListMethods`; model/generation/version strings do not substitute for an advertised method;\n- BLE provisioning may add a verified `wifiBaseUrl` to the same physical Plug through `Wifi.Scan` -> one `Wifi.SetConfig` -> read-only `Wifi.GetStatus`;\n- after a verified Wi-Fi locator exists, normal Detail/runtime/relay/firmware/time management is explicitly promoted to HTTP; this is deterministic transport promotion, not blind fallback;\n- firmware update sends one `Shelly.Update({ stage: \'stable\' })`; reboot ambiguity is resolved by read-only reconnect, canonical-id verification, expected-firmware verification and capability refresh;\n- `Sys.SetTime` is shown only when advertised; hardware proved 1.2.3 lacks it and 2.0.1 advertises it;\n- raw `OTA.*` methods observed on hardware are not part of the product contract because they are undocumented.'
assert old in s
s=s.replace(old,new)
old='`SavedBlePlug` must not be forced into HTTP `ShellyDraftDevice` with a fake `baseUrl`. A future dual-transport record may represent both locators for one physical Plug, but canonical identity remains normalized `Shelly.GetDeviceInfo.id` and transport selection must stay separate from business logic.'
new='`SavedBlePlug` is not forced into HTTP `ShellyDraftDevice` with a fake `baseUrl`. It may carry both replaceable `bleDeviceId` and optional verified `wifiBaseUrl` transport metadata on the same canonical physical record; normalized `Shelly.GetDeviceInfo.id` remains identity and transport selection stays separate from automation ownership.'
assert old in s
s=s.replace(old,new)
p.write_text(s)

p=Path('docs/PLUG_PROVISIONING_PLAN.md'); s=p.read_text()
repls={
'Status: active implementation plan for `work/shelly-ble-transport`.':'Status: **Slices A-C implemented and hardware-accepted on 2026-09-27; Slice D is next.**',
'Status: implemented. Real Plug S Gen3 firmware `1.2.3` exposed the missing-handler case and drove the capability-first contract.':'Status: **hardware accepted.** Firmware `1.2.3` exposed the missing-handler case; after accepted OTA to `2.0.1`, `Sys.SetTime` appeared in `Shelly.ListMethods` and the user confirmed synchronization works.',
'Status: software slice implemented; focused tests/build pass and Android development APK installed. Real scan/connect acceptance is next.':'Status: **hardware accepted.** Real BLE scan returned SSIDs; one `Wifi.SetConfig` connected successfully; `Wifi.GetStatus` returned `192.168.0.17`; the verified HTTP locator was persisted on the same Plug.',
'Status: package client foundation in progress.':'Status: **hardware accepted.** The real Plug reported stable `2.0.1`; one explicit update upgraded `1.2.3 -> 2.0.1`; read-only reconnect verified the same id and expected firmware, refreshed methods and reported no remaining stable update.',
'### Slice D - zero-friction onboarding orchestration':'### Slice D - zero-friction onboarding orchestration — NEXT',
'Do not implement an undocumented raw BLE DFU protocol as the product path.':'Do not implement an undocumented raw BLE DFU protocol as the product path. The tested Plug advertises raw `OTA.*` RPCs, but they are undocumented and deliberately remain unsupported.'
}
for a,b in repls.items():
    assert a in s, a
    s=s.replace(a,b,1)
p.write_text(s)

p=Path('docs/ROADMAP.md'); s=p.read_text()
start=s.index('### Read-only BLE Plug Detail / Device / Info — SOFTWARE DONE, HARDWARE ACCEPTANCE PENDING')
marker='The existing Wi-Fi/HTTP path remains stable and must not be refactored merely to make BLE reuse easier.'
end=s.index(marker,start)+len(marker)
rep='''### BLE Plug Detail + provisioning + OTA — HARDWARE ACCEPTED

Samsung SM-S906B / Android 16 hardware acceptance passed against factory Plug `shellyplugsg3-e4b063e3e298` (`S3PL-00112EU`). BLE Device/Info keeps LED/button/Cloud read-only, while capability-aware time sync, Wi-Fi provisioning and HTTP firmware maintenance are accepted. Real `Wifi.Scan` -> one `Wifi.SetConfig` produced verified HTTP locator `192.168.0.17` on the same canonical Plug. One explicit `Shelly.Update` upgraded `1.2.3 -> 2.0.1`; read-only reconnect verified the same id and expected firmware without replaying the update; `Sys.SetTime` became advertised and the user confirmed time sync works.

Hardware-tested source is `21d8675470a3d6425b0733cc708bdff55cb0d2cd`, APK SHA-256 `59c0bcbdc4122c565df43f3918437410ccca27a079acb790e634e7803dbd2c35`. Final software-gated descendant `5059feaaa654a2522f65b57bd0918652ac9a46ca` passes the full repository gate.

Next active work is the zero-friction onboarding state machine: discovery -> identity/capabilities -> Wi-Fi when needed -> HTTP handoff -> firmware check/update -> reconnect/verify -> final configuration -> Ready. Pairing/bonding for persistent BLE on firmware 2.x and offline OTA remain separate later slices.'''
s=s[:start]+rep+s[end:]
p.write_text(s)

p=Path('docs/testing/hardware-matrix.md'); s=p.read_text()
anchor='Current stabilization Shelly identity:'
row='| 2026-09-27 | S22+ BLE provisioning -> Wi-Fi -> OTA -> time sync | PASS | Samsung SM-S906B / Android 16 ran source `21d8675470a3d6425b0733cc708bdff55cb0d2cd`, APK SHA-256 `59c0bcbdc4122c565df43f3918437410ccca27a079acb790e634e7803dbd2c35`, installed with `adb install -r`. Factory Plug `shellyplugsg3-e4b063e3e298` returned real SSIDs; one `Wifi.SetConfig` connected and `Wifi.GetStatus` reported `192.168.0.17`; HTTP re-verification matched the same id. Firmware `1.2.3` lacked `Sys.SetTime` and offered stable `2.0.1`; one `Shelly.Update` upgraded it; read-only reconnect verified `fw_id=20260923-075613/2.0.1-ge1a198b`, empty `Shelly.CheckForUpdate` and `Sys.SetTime` in `Shelly.ListMethods`; the user confirmed time sync works. No automatic mutation replay and no relay mutation occurred. Final software descendant `5059feaaa654a2522f65b57bd0918652ac9a46ca` passed `pnpm check:full`: mobile 84/84 files, 381/381 tests; core 86/86; script coverage 138/138; responsive E2E 36/36. |\n\n'
assert anchor in s
if row not in s:
    s=s.replace(anchor,row+anchor,1)
p.write_text(s)
